from typing import List

def fizzbuzz_list(n: int) -> List[str]:
    """Return a list of strings for 1..n with Fizz/Buzz rules applied."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result
