def validate_password(pw):
    if not isinstance(pw, str):
        return False
    if not 8 <= len(pw) <= 64:
        return False
    if any(c.isspace() for c in pw):
        return False
    if not any(c.isupper() for c in pw):
        return False
    if not any(c.islower() for c in pw):
        return False
    if not any(c.isdigit() for c in pw):
        return False
    if not any(c in "!@#$%^&*" for c in pw):
        return False
    return True
